#!/usr/bin/env python3
"""Session folderization: copy active sessions, move dead sessions from logs to exports."""

import json
import os
import shutil
import sqlite3
import sys
from datetime import datetime
from pathlib import Path

WORK_DIR = Path("/Users/dk/lab-data/ai-suite")
LOG_DIR = WORK_DIR / ".opencode" / "logs"
EXPORT_DIR = WORK_DIR / "ai-session-exports" / "opencode-session-exports"
DB_PATH = Path("/Users/dk/lab-data/configurations-private/opencode/share/opencode.db")

DRY_RUN = "--dry-run" in sys.argv


def log(msg=""):
    print(msg)


def fmt_size(n: int) -> str:
    if n > 1_000_000:
        return f"{n/1_000_000:.1f}MB"
    if n > 1_000:
        return f"{n/1_000:.0f}KB"
    return f"{n}B"


def active_session_ids() -> set[str]:
    if not DB_PATH.exists():
        log(f"WARNING: DB not found at {DB_PATH}")
        return set()
    conn = sqlite3.connect(str(DB_PATH))
    cur = conn.cursor()
    cur.execute("SELECT id FROM session")
    ids = {row[0] for row in cur.fetchall()}
    conn.close()
    log(f"DB: {len(ids)} active sessions")
    return ids


def scan_logs():
    files: dict[str, list[Path]] = {}
    dirs: dict[str, Path] = {}
    for entry in LOG_DIR.iterdir():
        name = entry.name
        if entry.is_file():
            if not name.startswith("ses_"):
                continue
            sid = name.split(".", 1)[0]
            if sid.endswith(".turns"):
                sid = sid[:-6]
            files.setdefault(sid, []).append(entry)
        elif entry.is_dir() and name.startswith("ses_"):
            dirs[name] = entry
    # Merge dirs into files dict
    for sid in list(dirs.keys()):
        if sid not in files:
            files[sid] = []
    return files, dirs


def folderize():
    active = active_session_ids()
    session_files, session_dirs = scan_logs()
    log(f"Scanned: {len(session_files)} sessions in logs\n")

    counts = {"copied": 0, "moved": 0, "errors": 0, "skipped": 0}
    total_bytes = 0

    for sid in sorted(session_files.keys()):
        is_active = sid in active
        action = "COPY" if is_active else "MOVE"

        files = session_files[sid]
        turn_dir = session_dirs.get(sid)
        dest = EXPORT_DIR / sid

        if DRY_RUN:
            file_list = "  ".join(p.name for p in files)
            turn_info = f" +dir {turn_dir.name}" if turn_dir else ""
            log(f"  [{action}] {sid}  ({len(files)} files{turn_info})")
            continue

        try:
            dest.mkdir(parents=True, exist_ok=True)
            for src in files:
                dst = dest / src.name
                sz = src.stat().st_size
                total_bytes += sz
                if is_active:
                    shutil.copy2(src, dst)
                else:
